import {objectToQuery} from '@jetbrains/teamcity-ui/dist/utils'
import {connect} from 'react-redux'

import type {State} from '../../../reducers/types'
import {getSingleBuildArg} from '../../../rest/builds'
import {getBuildLocator} from '../../../rest/locators'
import {getOverviewHref} from '../../../routes'
import {
  getBuild,
  getPipelineBatchIdFromBuildId,
  getPipelineJobIdFromBuildId,
  getPipelineRunIdFromBuildId,
  getPipelineIdFromBuildId,
} from '../../../selectors'
import {restApi} from '../../../services/rest'
import {getDuration} from '../../../utils/buildStats'

import BuildInfo from './BuildInfo'
import type {OwnProps, StateProps, Props} from './BuildInfo.types'

const mapStateToProps = (state: State, {buildId}: OwnProps): StateProps => {
  const build = getBuild(state, buildId)
  const {
    status = 'UNKNOWN',
    statusText = '',
    startDate,
    finishDate,
    ['running-info']: runningInfo,
    buildType: buildTypeId,
  } = build || {}
  const duration = getDuration({startDate, finishDate, runningInfo})
  const pipelineId = getPipelineIdFromBuildId(state, buildId)
  const runId = getPipelineRunIdFromBuildId(state, buildId)
  const jobId = getPipelineJobIdFromBuildId(state, buildId)
  const batchId = getPipelineBatchIdFromBuildId(state, buildId)
  const href = getOverviewHref({
    buildId,
    buildTypeId,
    pipelineId,
    runId,
  }).concat(
    jobId ? `?${objectToQuery({job: jobId ?? null, pageFullLogBuildId: batchId ?? null})}` : '',
  )
  return {
    href,
    status,
    duration,
    startDate,
    finishDate,
    statusText,
    buildTypeId,
    left: runningInfo?.leftSeconds,
    progress: runningInfo?.percentageComplete,
    running: build?.state === 'running',
    loading: build == null || build.state === 'queued',
  }
}

function BuildInfoContainer(props: Props) {
  const {loading, withFetchBuildData, buildId} = props
  const locator = getBuildLocator(buildId)
  restApi.endpoints.getBuildNormalized.useQuerySubscription(getSingleBuildArg(locator), {
    skip: !withFetchBuildData,
  })
  restApi.endpoints.getBuildNormalized.useQuery(
    getSingleBuildArg(locator, {
      withShortBuildDetails: true,
      withPipelineRuns: true,
      withAnchorBuild: true,
    }),
    {skip: !withFetchBuildData},
  )
  return loading ? null : <BuildInfo {...props} />
}
export default connect(mapStateToProps)(BuildInfoContainer)
