import {produce} from 'immer'

import {useCallback, useEffect} from 'react'
import {graphql, useFragment, useRelayEnvironment} from 'react-relay'
import {createOperationDescriptor, getRequest} from 'relay-runtime'

import type {BuildId} from '../../types'
import type {Unsubscribe} from '../../utils/subscriber'
import {subscribeOnBuildTypeEvents, subscribeOnRunningBuild} from '../../utils/subscriber'
import {
  BUILD_FINISHED,
  BUILD_INTERRUPTED,
  BUILD_STARTED,
  BUILD_TYPE_REMOVED_FROM_QUEUE,
} from '../../utils/subscriptionEvents'

import type {useRunningBuildUpdaterRelayFragment$key} from './__generated__/useRunningBuildUpdaterRelayFragment.graphql'
import {useOnDemandQuery} from './useOnDemandQuery'

const fragment = graphql`
  fragment useRunningBuildUpdaterRelayFragment on Build {
    id
    state
    buildType {
      internalId
    }
  }
`

const query = graphql`
  query useRunningBuildUpdaterRelayQuery($locator: String!) {
    build(buildLocator: $locator) {
      buildTypeId
      number
      runningInfo {
        percentageComplete
        elapsedSeconds
        estimatedTotalSeconds
        leftSeconds
        currentStageText
        probablyHanging
        lastActivityTime
        outdated
        outdatedReasonBuild {
          id
          number
          links {
            link {
              relativeUrl
            }
          }
        }
      }
      canceledInfo {
        timestamp
        text
        user {
          id
          name
          username
        }
      }
      statusText
      status
      state
      detachedFromAgent
      finishOnAgentDate
      personal
      artifacts {
        count
      }
      testOccurrences {
        count
      }
      agent {
        connected
      }
      failedToStart
    }
  }
`

const emptyData = {
  buildTypeId: null,
  number: null,
  runningInfo: null,
  canceledInfo: null,
  statusText: null,
  status: null,
  state: null,
  detachedFromAgent: null,
  finishOnAgentDate: null,
  personal: null,
  artifacts: null,
  testOccurrences: null,
  agent: null,
}

const countSubscriptions: Record<BuildId, number> = {}
const unsubscribeFunctions: Record<BuildId, Unsubscribe> = {}
export function useRunningBuildUpdaterRelay(key: useRunningBuildUpdaterRelayFragment$key | null) {
  const {id, state, buildType} = useFragment(fragment, key) ?? {}
  const environment = useRelayEnvironment()
  const refetch = useOnDemandQuery(query)
  const subscribe = useCallback(() => {
    const unsubscribeFromBuild =
      id != null
        ? subscribeOnRunningBuild(id, data => {
            if (data != null) {
              environment.commitPayload(
                createOperationDescriptor(getRequest(query), {locator: `id:${id}`}),
                {
                  build: produce<any>({...emptyData, ...data}, draft => {
                    draft._id = `Build:${draft.id}`
                    draft.canceledInfo ??= null
                    if (draft.canceledInfo != null) {
                      draft.canceledInfo.user ??= null
                      if (draft.canceledInfo.user != null) {
                        draft.canceledInfo.user._id = `User:${draft.canceledInfo.user.id}`
                      }
                    }
                    draft.runningInfo = draft['running-info'] ?? null
                    delete draft['running-info']
                    if (draft.runningInfo != null) {
                      draft.runningInfo.leftSeconds ??= null
                      draft.runningInfo.lastActivityTime ??= null
                      draft.runningInfo.outdatedReasonBuild ??= null
                      if (draft.runningInfo.outdatedReasonBuild != null) {
                        draft.runningInfo.outdatedReasonBuild._id = `Build:${draft.runningInfo.outdatedReasonBuild.id}`
                      }
                    }
                    draft.agent = draft.agent ?? null
                    if (draft.agent != null) {
                      draft.agent._id = `Agent:${draft.agent.id}`
                    }
                    draft.failedToStart ??= null
                  }),
                },
              )
            }
          })
        : undefined

    const unsubscribeFromBuildType =
      buildType?.internalId != null
        ? subscribeOnBuildTypeEvents(
            buildType.internalId,
            [BUILD_STARTED, BUILD_TYPE_REMOVED_FROM_QUEUE, BUILD_FINISHED, BUILD_INTERRUPTED],
            () => refetch({locator: `id:${id}`}, true),
          )
        : null
    return () => {
      unsubscribeFromBuild?.()
      unsubscribeFromBuildType?.()
    }
  }, [buildType?.internalId, environment, id, refetch])
  useEffect(() => {
    if (id != null && (state === 'queued' || state === 'running')) {
      const prevCount = countSubscriptions[id] ?? 0

      if (prevCount === 0) {
        unsubscribeFunctions[id] = subscribe()
      }

      countSubscriptions[id] = prevCount + 1
      return () => {
        countSubscriptions[id] -= 1

        if (countSubscriptions[id] === 0) {
          unsubscribeFunctions[id]()
          delete countSubscriptions[id]
          delete unsubscribeFunctions[id]
        }
      }
    } else {
      return undefined
    }
  }, [buildType?.internalId, environment, id, refetch, state, subscribe])
}
